"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["32405"],{57983(e){e.exports=JSON.parse('{"id":"FIN-502","slug":"medium-of-exchange","term":"Medium of Exchange","also_known_as":[],"difficulty":"Beginner","definition":"A medium of exchange is anything widely accepted in payment for goods and services. It is the function of money that makes buying and selling easy.","explanation":["Without a medium of exchange, people would have to barter, swapping goods directly. A farmer wanting shoes would need to find a shoemaker who also wanted vegetables at that moment. A medium of exchange removes this problem, because everyone accepts it and can spend it on whatever they need.","To work well, a medium of exchange must be widely trusted, easy to carry, hard to fake and divisible into small amounts. Coins, banknotes and bank balances moved by card or transfer all meet these tests in modern economies.","History shows many other examples. Shells, salt, cattle, cigarettes in prisons and precious metals have all served as media of exchange when people agreed to accept them.","Something can be a medium of exchange without being a good store of value. A currency suffering from high inflation may still be used for everyday purchases, but people try to spend it quickly before it loses value. Some cryptocurrencies face the opposite challenge: they may be held as investments but are not widely accepted for everyday payments."],"note":"","total":1500,"prev":{"slug":"median","term":"Median"},"next":{"slug":"merger","term":"Merger"}}')}}]);